import java.util.*;

class LRUCache {
    private static class Node {
        int key;
        int value;
        Node prev;
        Node next;

        Node(int key, int value) {
            this.key = key;
            this.value = value;
        }
    }

    private final int capacity;
    private final Map<Integer, Node> nodes = new HashMap<>();
    private final Node head = new Node(-1, -1);
    private final Node tail = new Node(-1, -1);

    public LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node node = nodes.get(key);
        if (node == null) {
            return -1;
        }
        moveToFront(node);
        return node.value;
    }

    public void put(int key, int value) {
        Node node = nodes.get(key);
        if (node != null) {
            node.value = value;
            moveToFront(node);
            return;
        }

        Node inserted = new Node(key, value);
        nodes.put(key, inserted);
        insertAfterHead(inserted);

        if (nodes.size() > capacity) {
            Node leastRecent = tail.prev;
            unlink(leastRecent);
            nodes.remove(leastRecent.key);
        }
    }

    private void moveToFront(Node node) {
        unlink(node);
        insertAfterHead(node);
    }

    private void unlink(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void insertAfterHead(Node node) {
        node.prev = head;
        node.next = head.next;
        head.next.prev = node;
        head.next = node;
    }
}

import java.util.*;

class LRUCache extends LinkedHashMap<Integer, Integer> {
    private final int capacity;

    public LRUCache(int capacity) {
        super(capacity, 0.75f, true);
        this.capacity = capacity;
    }

    public int get(int key) {
        return super.getOrDefault(key, -1);
    }

    public void put(int key, int value) {
        super.put(key, value);
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<Integer, Integer> eldest) {
        return size() > capacity;
    }
}

class LRUCache {
    private static final int MAX_KEY = 10000;

    private static class Node {
        int key;
        int value;
        Node prev;
        Node next;

        Node(int key, int value) {
            this.key = key;
            this.value = value;
        }
    }

    private final int capacity;
    private int size;
    private final Node[] table = new Node[MAX_KEY + 1];
    private final Node head = new Node(-1, -1);
    private final Node tail = new Node(-1, -1);

    public LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node node = table[key];
        if (node == null) {
            return -1;
        }
        moveToFront(node);
        return node.value;
    }

    public void put(int key, int value) {
        Node node = table[key];
        if (node != null) {
            node.value = value;
            moveToFront(node);
            return;
        }

        Node inserted = new Node(key, value);
        table[key] = inserted;
        insertAfterHead(inserted);
        size++;

        if (size > capacity) {
            Node leastRecent = tail.prev;
            unlink(leastRecent);
            table[leastRecent.key] = null;
            size--;
        }
    }

    private void moveToFront(Node node) {
        unlink(node);
        insertAfterHead(node);
    }

    private void unlink(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void insertAfterHead(Node node) {
        node.prev = head;
        node.next = head.next;
        head.next.prev = node;
        head.next = node;
    }
}

class LRUCache {
    private static final int MAX_KEY = 10000;
    private static final int HEAD = MAX_KEY + 1;
    private static final int TAIL = MAX_KEY + 2;

    private final int capacity;
    private int size;
    private final int[] values = new int[MAX_KEY + 3];
    private final int[] prev = new int[MAX_KEY + 3];
    private final int[] next = new int[MAX_KEY + 3];
    private final boolean[] present = new boolean[MAX_KEY + 1];

    public LRUCache(int capacity) {
        this.capacity = capacity;
        next[HEAD] = TAIL;
        prev[TAIL] = HEAD;
    }

    public int get(int key) {
        if (!present[key]) {
            return -1;
        }
        moveToFront(key);
        return values[key];
    }

    public void put(int key, int value) {
        if (present[key]) {
            values[key] = value;
            moveToFront(key);
            return;
        }

        if (size == capacity) {
            int leastRecent = prev[TAIL];
            unlink(leastRecent);
            present[leastRecent] = false;
            size--;
        }

        values[key] = value;
        present[key] = true;
        insertAfterHead(key);
        size++;
    }

    private void moveToFront(int key) {
        unlink(key);
        insertAfterHead(key);
    }

    private void unlink(int key) {
        int before = prev[key];
        int after = next[key];
        next[before] = after;
        prev[after] = before;
    }

    private void insertAfterHead(int key) {
        int first = next[HEAD];
        prev[key] = HEAD;
        next[key] = first;
        prev[first] = key;
        next[HEAD] = key;
    }
}
